import { HttpException } from '@nestjs/common';
import { Test, TestingModule } from '@nestjs/testing';
import { AdminController } from './admin.controller';
import { AdminService } from './admin.service';
import { PlantWithConfigDto } from './dto/plant-dto';
import { PlantWithConfig } from './interfaces/plant-with-config.model';

describe('AdminController', () => {
  let controller: AdminController;
  let adminService: AdminService;

  // Test constants
  const DEFAULT_AGGR_TIME = 60;
  const DEFAULT_ALERT_CREATION = 'MANUAL';
  const DEFAULT_OFFSET_FROM = 0;
  const DEFAULT_OFFSET_TO = 220;
  const DEFAULT_TOLERANCE = 60;
  const ERROR_MESSAGE = 'Test error';
  const PLANT_ID = 1001;
  const TEST_PLANT_DESC = 'Test Plant';
  const TEST_UPDATED_PLANT_DESC = 'Updated Plant';
  const UPDATED_AGGR_TIME = 90;
  const UPDATED_ALERT_CREATION = 'AUTOMATIC';
  const UPDATED_OFFSET_TO = 240;
  const UPDATED_TOLERANCE = 90;

  beforeEach(async () => {
    // Create mock AdminService
    const mockAdminService = {
      addPlantWithConfig: jest.fn(),
      deletePlantWithConfig: jest.fn(),
      fetchPlantWithConfig: jest.fn(),
      updatePlantWithConfig: jest.fn(),
    };

    const module: TestingModule = await Test.createTestingModule({
      controllers: [AdminController],
      providers: [
        {
          provide: AdminService,
          useValue: mockAdminService,
        },
      ],
    }).compile();

    controller = module.get<AdminController>(AdminController);
    adminService = module.get<AdminService>(AdminService);
  });

  it('should be defined', () => {
    expect(controller).toBeDefined();
  });

  describe('createPlantWithConfig', () => {
    it('should successfully create a plant with config without pickingTimeHorizon', async () => {
      // Create a test DTO without pickingTimeHorizon
      const plantWithConfigDto: PlantWithConfigDto = {
        aggrTimeLvlBoard: DEFAULT_AGGR_TIME,
        alertCreation: DEFAULT_ALERT_CREATION,
        ewmFlow: true,
        offsetFrom: DEFAULT_OFFSET_FROM,
        offsetTo: DEFAULT_OFFSET_TO,
        plantDesc: TEST_PLANT_DESC,
        plantId: PLANT_ID,
        toleranceValueWk: DEFAULT_TOLERANCE,
      };

      // Expected result without pickingTimeHorizon
      const expectedResult: PlantWithConfig = {
        aggrTimeLvlBoard: DEFAULT_AGGR_TIME,
        alertCreation: DEFAULT_ALERT_CREATION,
        ewmFlow: true,
        offsetTo: DEFAULT_OFFSET_TO,
        plantDesc: TEST_PLANT_DESC,
        plantId: PLANT_ID,
        sid: undefined,
        timezone: undefined,
        toleranceValueWk: DEFAULT_TOLERANCE,
      };

      // Set up the mock to return our expected result
      const addPlantWithConfigMock = jest
        .fn()
        .mockResolvedValue(expectedResult);
      adminService.addPlantWithConfig = addPlantWithConfigMock;

      // Call the controller method
      const result = await controller.createPlantWithConfig(plantWithConfigDto);

      // Verify that the service was called with the correct DTO
      expect(addPlantWithConfigMock).toHaveBeenCalledWith(plantWithConfigDto);

      // Verify the result doesn't have pickingTimeHorizon
      expect(result).not.toHaveProperty('pickingTimeHorizon');
      expect(result).toEqual(expectedResult);
    });

    it('should handle errors when creating plant with config', async () => {
      // Create a test DTO without pickingTimeHorizon
      const plantWithConfigDto: PlantWithConfigDto = {
        aggrTimeLvlBoard: DEFAULT_AGGR_TIME,
        alertCreation: DEFAULT_ALERT_CREATION,
        ewmFlow: true,
        offsetFrom: DEFAULT_OFFSET_FROM,
        offsetTo: DEFAULT_OFFSET_TO,
        plantDesc: TEST_PLANT_DESC,
        plantId: PLANT_ID,
        toleranceValueWk: DEFAULT_TOLERANCE,
      };

      // Set up the mock to throw an error
      adminService.addPlantWithConfig = jest
        .fn()
        .mockRejectedValue(new Error(ERROR_MESSAGE));

      // Call the controller method and expect it to throw
      await expect(
        controller.createPlantWithConfig(plantWithConfigDto),
      ).rejects.toThrow(HttpException);
    });
  });

  describe('updatePlantWithConfig', () => {
    it('should successfully update a plant with config without pickingTimeHorizon', async () => {
      // Create a test DTO without pickingTimeHorizon
      const plantWithConfigDto: PlantWithConfigDto = {
        aggrTimeLvlBoard: UPDATED_AGGR_TIME,
        alertCreation: UPDATED_ALERT_CREATION,
        ewmFlow: false,
        offsetFrom: DEFAULT_OFFSET_FROM,
        offsetTo: UPDATED_OFFSET_TO,
        plantDesc: TEST_UPDATED_PLANT_DESC,
        plantId: PLANT_ID,
        toleranceValueWk: UPDATED_TOLERANCE,
      };

      // Expected result without pickingTimeHorizon
      const expectedResult: PlantWithConfig = {
        aggrTimeLvlBoard: UPDATED_AGGR_TIME,
        alertCreation: UPDATED_ALERT_CREATION,
        ewmFlow: false,
        offsetTo: UPDATED_OFFSET_TO,
        plantDesc: TEST_UPDATED_PLANT_DESC,
        plantId: PLANT_ID,
        sid: undefined,
        timezone: undefined,
        toleranceValueWk: UPDATED_TOLERANCE,
      };

      // Set up the mock to return our expected result
      const updatePlantWithConfigMock = jest
        .fn()
        .mockResolvedValue(expectedResult);
      adminService.updatePlantWithConfig = updatePlantWithConfigMock;

      // Call the controller method
      const result = await controller.updatePlantWithConfig(
        PLANT_ID,
        plantWithConfigDto,
      );

      // Verify that the service was called with the correct ID and DTO
      expect(updatePlantWithConfigMock).toHaveBeenCalledWith(
        PLANT_ID,
        plantWithConfigDto,
      );

      // Verify the result doesn't have pickingTimeHorizon
      expect(result).not.toHaveProperty('pickingTimeHorizon');
      expect(result).toEqual(expectedResult);
    });

    it('should handle errors when updating plant with config', async () => {
      // Create a test DTO without pickingTimeHorizon
      const plantWithConfigDto: PlantWithConfigDto = {
        aggrTimeLvlBoard: UPDATED_AGGR_TIME,
        alertCreation: UPDATED_ALERT_CREATION,
        ewmFlow: false,
        offsetFrom: DEFAULT_OFFSET_FROM,
        offsetTo: UPDATED_OFFSET_TO,
        plantDesc: TEST_UPDATED_PLANT_DESC,
        plantId: PLANT_ID,
        toleranceValueWk: UPDATED_TOLERANCE,
      };

      // Set up the mock to throw an error
      adminService.updatePlantWithConfig = jest
        .fn()
        .mockRejectedValue(new Error(ERROR_MESSAGE));

      // Call the controller method and expect it to throw
      await expect(
        controller.updatePlantWithConfig(PLANT_ID, plantWithConfigDto),
      ).rejects.toThrow(HttpException);
    });
  });

  describe('fetchPlantWithConfig', () => {
    it('should fetch plant with config without pickingTimeHorizon', async () => {
      // Expected result without pickingTimeHorizon
      const expectedResult: PlantWithConfig = {
        aggrTimeLvlBoard: DEFAULT_AGGR_TIME,
        alertCreation: DEFAULT_ALERT_CREATION,
        ewmFlow: true,
        offsetTo: DEFAULT_OFFSET_TO,
        plantDesc: TEST_PLANT_DESC,
        plantId: PLANT_ID,
        sid: undefined,
        timezone: undefined,
        toleranceValueWk: DEFAULT_TOLERANCE,
      };

      // Set up the mock to return our expected result
      const fetchPlantWithConfigMock = jest
        .fn()
        .mockResolvedValue(expectedResult);
      adminService.fetchPlantWithConfig = fetchPlantWithConfigMock;

      // Call the controller method
      const result = await controller.fetchPlantWithConfig(PLANT_ID);

      // Verify that the service was called with the correct ID
      expect(fetchPlantWithConfigMock).toHaveBeenCalledWith(PLANT_ID);

      // Verify the result doesn't have pickingTimeHorizon
      expect(result).not.toHaveProperty('pickingTimeHorizon');
      expect(result).toEqual(expectedResult);
    });
  });
});

import {
  Controller,
  Get,
  Post,
  Put,
  Delete,
  Param,
  Body,
  HttpException,
  HttpStatus,
  ParseIntPipe,
  InternalServerErrorException,
  NotFoundException,
  Res,
  UseFilters,
} from '@nestjs/common';
import {
  ApiTags,
  ApiOperation,
  ApiResponse,
  ApiBody,
  ApiParam,
} from '@nestjs/swagger';
import { Response } from 'express';
import { AdminService } from './admin.service';
import { PlantWithConfigDto } from './dto/plant-dto';
import { ResourceWithMesInfoResponseDto } from './dto/resource-with-mes-info.response.dto';
import { ResourceDto } from './dto/resource.dto';
import { StorageLocationResponseDTO } from './dto/storage-location.response.dto';
import { UpdateEwmWipDTO } from './dto/update-ewm-dto';
import { UpdateResourceParameterDto } from './dto/update-resource-parameter.dto';
import { UpdateWorkcenter } from './dto/update-workcenter.dto';
import { WorkcenterPlantDto } from './dto/workcenter-plant.dto';
import { WorkcenterResponse } from './dto/workcenter-response.dto';
import { PlanHierarchy } from './interfaces/plant-hierarchy.model';
import { PlantWithConfig } from './interfaces/plant-with-config.model';
import { Plant } from './interfaces/plant.model';
import { MaterialRequestDto } from '@/admin/dto/material-request.dto';
import { WorkcentersDTO } from '@/admin/dto/workcenters.dto';
import { MesGenericErrorFilter } from '@/bom/filters/mes-generic-error.filter';

@ApiTags('Admin')
@Controller('admin')
export class AdminController {
  public constructor(private readonly adminService: AdminService) {}

  @Get('plants')
  @ApiOperation({ summary: 'Fetch all plants' })
  @ApiResponse({
    status: 200,
    description: 'Returns an array of plants.',
    type: [PlantWithConfigDto],
  })
  @ApiResponse({ status: 400, description: 'Bad request.' })
  public async fetchPlants(): Promise<Array<Plant>> {
    try {
      return await this.adminService.fetchPlants();
    } catch {
      throw new HttpException('Failed to fetch plants', HttpStatus.BAD_REQUEST);
    }
  }

  @Get('/getAllMaterial/:plant')
  public async getAllMaterial(
    @Param('plant') plant: string,
    @Res() response: Response,
  ): Promise<Response> {
    try {
      const result =
        await this.adminService.getMaterialsByPlantAndSapServer(plant);
      return response.status(HttpStatus.OK).json(result);
    } catch (error) {
      if (error instanceof HttpException) {
        throw error;
      }

      // Wrap unexpected errors
      throw new HttpException(
        `Failed to retrieve material details for plant ${plant}`,
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  // Fetch plant and config by ID
  @Get('plant-with-config/:id')
  @ApiOperation({ summary: 'Fetch plant and its configuration by ID' })
  @ApiParam({ name: 'id', description: 'Plant ID' })
  @ApiResponse({
    status: 200,
    description: 'Returns a plant with its configuration.',
    type: PlantWithConfigDto,
  })
  @ApiResponse({
    status: 404,
    description: 'Plant or configuration not found.',
  })
  public async fetchPlantWithConfig(
    @Param('id') id: number,
  ): Promise<PlantWithConfig> {
    try {
      return await this.adminService.fetchPlantWithConfig(id);
    } catch {
      throw new HttpException(
        'Failed to fetch plant with configuration',
        HttpStatus.NOT_FOUND,
      );
    }
  }

  // Create new plant and config
  @Post('plant-with-config')
  @ApiOperation({ summary: 'Create a new plant with its configuration' })
  @ApiBody({
    type: PlantWithConfigDto,
    description: 'Plant and configuration data',
  })
  @ApiResponse({
    status: 201,
    description: 'The plant with configuration has been successfully created.',
    type: PlantWithConfigDto,
  })
  @ApiResponse({ status: 400, description: 'Bad request.' })
  public async createPlantWithConfig(
    @Body() plantWithConfigDto: PlantWithConfigDto,
  ): Promise<PlantWithConfig> {
    try {
      return await this.adminService.addPlantWithConfig(plantWithConfigDto);
    } catch (error) {
      console.error('Error creating plant with configuration:', error);
      const errorMessage =
        error instanceof Error
          ? `Failed to create plant with configuration: ${error.message}`
          : 'Failed to create plant with configuration';

      throw new HttpException(errorMessage, HttpStatus.BAD_REQUEST);
    }
  }

  @ApiOperation({ summary: 'Bulk update workcenters for a given plant' })
  @ApiParam({ description: 'Plant ID', name: 'plant', type: Number })
  @ApiResponse({
    description: 'Invalid input or missing workcenters',
    status: 400,
  })
  @Post('workcenter/bulkUpdate/:plant')
  public async updateWorkcentersBulk(
    @Param('plant') plant: number,
    @Body() updateDtos: Array<WorkcentersDTO>,
    @Res() response: Response,
  ): Promise<Response> {
    const result = await this.adminService.updateWorkcentersBulk(
      plant,
      updateDtos,
    );
    return response.status(HttpStatus.OK).json(result);
  }

  @ApiOperation({ summary: 'mass  update materials for a given plant' })
  @ApiParam({ description: 'Plant ID', name: 'plant', type: Number })
  @ApiResponse({
    description: 'Invalid input or missing materials',
    status: 400,
  })
  @Post('material/massUpdate/:plant')
  public async updateMaterialsBulk(
    @Param('plant') plant: string,
    @Body() updateDtos: Array<MaterialRequestDto>,
    @Res() response: Response,
  ): Promise<Response> {
    const result =
      await this.adminService.updateMaterialsBulkByPlantAndSapServer(
        plant,
        updateDtos,
      );
    return response.status(HttpStatus.OK).json(result);
  }

  // Update plant and config by ID
  @Put('plant-with-config/:id')
  @ApiOperation({ summary: 'Update a plant and its configuration by ID' })
  @ApiParam({ name: 'id', description: 'Plant ID' })
  @ApiBody({
    type: PlantWithConfigDto,
    description: 'Updated plant and configuration data',
  })
  @ApiResponse({
    status: 200,
    description: 'The plant with configuration has been successfully updated.',
    type: PlantWithConfigDto,
  })
  @ApiResponse({
    status: 404,
    description: 'Plant or configuration not found.',
  })
  public async updatePlantWithConfig(
    @Param('id') id: number,
    @Body() plantWithConfigDto: PlantWithConfigDto,
  ): Promise<PlantWithConfig> {
    try {
      return await this.adminService.updatePlantWithConfig(
        id,
        plantWithConfigDto,
      );
    } catch (error) {
      console.error('Error updating plant with configuration:', error);
      const errorMessage =
        error instanceof Error
          ? `Failed to update plant with configuration: ${error.message}`
          : 'Failed to update plant with configuration';

      throw new HttpException(errorMessage, HttpStatus.NOT_FOUND);
    }
  }

  // Delete plant and config by ID
  @Delete('plant-with-config/:id')
  @ApiOperation({ summary: 'Delete a plant and its configuration by ID' })
  @ApiParam({ name: 'id', description: 'Plant ID' })
  @ApiResponse({
    status: 200,
    description: 'The plant and configuration have been successfully deleted.',
  })
  @ApiResponse({
    status: 404,
    description: 'Plant or configuration not found.',
  })
  public async deletePlantWithConfig(
    @Param('id') id: number,
  ): Promise<{ response: string }> {
    try {
      await this.adminService.deletePlantWithConfig(id);
      return { response: 'Plant and configuration successfully deleted.' };
    } catch {
      throw new HttpException(
        'Failed to delete plant with configuration',
        HttpStatus.NOT_FOUND,
      );
    }
  }

  @Get('check-deleted/:plantId')
  @ApiOperation({ summary: 'Check if a plant is deleted' })
  @ApiParam({
    name: 'plantId',
    type: 'integer',
    description: 'The ID of the plant to check',
  })
  @ApiResponse({
    status: 200,
    description: 'Returns true if the plant is deleted, false if not deleted.',
  })
  @ApiResponse({ status: 404, description: 'Plant not found.' })
  public async checkDeletedPlant(
    @Param('plantId', ParseIntPipe) plantId: number,
  ): Promise<boolean | undefined> {
    try {
      return await this.adminService.checkDeletedPlant(plantId);
    } catch {
      throw new HttpException(
        'Failed to check deleted plant',
        HttpStatus.NOT_FOUND,
      );
    }
  }

  @ApiOperation({ summary: 'Fetch all the workcentrs by plant ID' })
  @ApiParam({ description: 'Plant ID', name: 'plant' })
  @ApiResponse({
    description: 'Returns a list of work centrs',
    status: 200,
    type: Array<WorkcentersDTO>,
  })
  @ApiResponse({
    description: 'Plant or configuration not found.',
    status: 404,
  })
  @Get('workcenters/get-all/:plant/')
  public async getAllWorkcenters(
    @Param('plant', ParseIntPipe) plant: number,
  ): Promise<Array<WorkcentersDTO>> {
    try {
      return await this.adminService.getAllWorkcenters(plant);
    } catch {
      throw new HttpException(
        'Failed to check deleted plant',
        HttpStatus.NOT_FOUND,
      );
    }
  }

  @ApiOperation({ summary: 'Fetch all MES workcentrs by plant ID' })
  @ApiParam({ description: 'Plant ID', name: 'plant' })
  @ApiResponse({
    description: 'Returns a list of work centrs',
    status: 200,
    type: Array<WorkcenterPlantDto>,
  })
  @ApiResponse({
    description: 'Plant or configuration not found.',
    status: 404,
  })
  @Get('get-mes-workcenter/:plant/')
  public async getMesWorkcenters(
    @Param('plant', ParseIntPipe) plant: number,
  ): Promise<Array<WorkcenterPlantDto>> {
    try {
      return await this.adminService.getMesWorkcenters(plant);
    } catch {
      throw new HttpException(
        'failed to fetch mes workcenters ',
        HttpStatus.NOT_FOUND,
      );
    }
  }

  @ApiOperation({ summary: 'update the work center' })
  @ApiParam({ description: 'Plant ID', name: 'plant' })
  @ApiParam({ description: 'work center id ', name: 'workcenterId' })
  @ApiResponse({
    description: 'Returns a  work centrs',
    status: 200,
    type: WorkcentersDTO,
  })
  @ApiResponse({
    description: 'Failed to update workcenter.',
    status: 500,
  })
  @Put('workcenter/:plant/:workcenterId')
  public async updateWorkcenter(
    @Param('plant') plant: number,
    @Param('workcenterId') workcenterId: string,
    @Body() updateDto: WorkcentersDTO,
  ): Promise<WorkcentersDTO> {
    try {
      return await this.adminService.updateWorkcenter(
        workcenterId,
        plant,
        updateDto,
      );
    } catch (error) {
      // Handle the error (e.g., logging it, rethrowing a custom exception)
      console.error('Error updating workcenter:', error);
      throw new HttpException(
        'Failed to update workcenter',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  @Get('/allStorageLocations/:plant')
  public async getAllStorageLocationsByPlant(
    @Param('plant') plant: number,
  ): Promise<Array<StorageLocationResponseDTO>> {
    try {
      return await this.adminService.getAllStorageLocations(plant);
    } catch (error) {
      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to retrieve storageLocations',
              error,
            );
      throw errorN;
    }
  }

  @Put('/updateEwmWip')
  public async updateEwmWip(
    @Body() updateData: UpdateEwmWipDTO,
  ): Promise<StorageLocationResponseDTO> {
    try {
      return await this.adminService.updateEwmWip(updateData);
    } catch (error) {
      const errorN =
        error instanceof NotFoundException
          ? error
          : new InternalServerErrorException(
              'Failed to update isEwmWip',
              error,
            );
      throw errorN;
    }
  }

  @Put('/material/updateMaterial/:plant?')
  public async updateMaterial(
    @Body() updateDto: MaterialRequestDto,
    @Res() response: Response,
    @Param('plant') plant?: string, // Optional plant if sapServer missing
  ): Promise<Response> {
    try {
      const result = await this.adminService.updateMaterial(updateDto, plant);
      return response.status(HttpStatus.OK).json(result);
    } catch (error) {
      // Handle the error (e.g., logging it, rethrowing a custom exception)
      console.error('Error updating material:', error);
      throw new HttpException(
        'Failed to update material',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  @Put('update-mes-wc/:plant/:workcenterId')
  @ApiOperation({
    summary: 'Update MES flag for a workcenter',
    description:
      'Updates the `isMes` flag for a given workcenter by plant and workcenterId.',
  })
  @ApiParam({
    name: 'plant',
    description: 'Plant code',
    type: Number,
    example: 1146,
  })
  @ApiParam({
    name: 'workcenterId',
    description: 'Workcenter unique ID',
    type: String,
    example: '12345728',
  })
  @ApiResponse({
    status: 200,
    description: 'Workcenter updated successfully',
    type: WorkcenterResponse,
  })
  @ApiResponse({
    status: 400,
    description: 'Validation error (e.g. isMes must be boolean)',
  })
  public async updateMesWorkcenter(
    @Param('plant') plant: number,
    @Param('workcenterId') workcenterId: string,
    @Body() updateDto: UpdateWorkcenter,
  ): Promise<WorkcenterResponse> {
    try {
      const result = await this.adminService.updateMesWorkcenter(
        workcenterId,
        plant,
        updateDto,
      );
      return result;
    } catch {
      throw new HttpException(
        'An error occurred while updating the workcenter',
        HttpStatus.INTERNAL_SERVER_ERROR,
      );
    }
  }

  @Get('/getResourcesByPlant/:plant')
  @UseFilters(MesGenericErrorFilter)
  @ApiResponse({
    description: 'The list of resource ids',
    status: 200,
    type: Array<string>,
  })
  @ApiParam({
    description: 'The plant ID for which resource IDs are to be fetched',
    name: 'plant',
    type: Number,
  })
  @ApiResponse({ description: 'resource not found.', status: 404 })
  public async getResourcesIdsByPlant(
    @Param('plant') plant: number,
    @Res() response: Response,
  ): Promise<Response> {
    const result = await this.adminService.fetchResourceByPlant(plant);
    return response.status(HttpStatus.OK).json(result);
  }

  @Get('/get-resource-by-id/:plant/:resourceId')
  @UseFilters(MesGenericErrorFilter)
  @ApiParam({
    description: 'The plant ID for which resource  are to be fetched',
    name: 'plant',
    type: Number,
  })
  @ApiParam({
    description: 'The resouce ID for which resource  to be fetched',
    name: 'resourceId',
    type: String,
  })
  @ApiResponse({
    description: 'The  resource by plant and id ',
    status: 200,
    type: ResourceDto,
  })
  @ApiResponse({ description: 'resource not found.', status: 404 })
  public async getResourceWithMesInfo(
    @Param('plant') plant: number,
    @Param('resourceId') resourceId: string,
    @Res() response: Response,
  ): Promise<Response> {
    const result =
      await this.adminService.fetchResourceDetailsByPlantAndResourceId(
        plant,
        resourceId,
      );
    return response.status(HttpStatus.OK).json(result);
  }

  @Get('/get-resource-by-plant/:plant')
  @UseFilters(MesGenericErrorFilter)
  @ApiParam({
    description: 'The plant ID for which resource  are to be fetched',
    name: 'plant',
    type: Number,
  })
  @ApiResponse({
    description: 'The  resource by plant and id ',
    status: 200,
    type: Array<ResourceWithMesInfoResponseDto>,
  })
  @ApiResponse({ description: 'resource not found.', status: 404 })
  public async getResourceWithMesInfoByPlant(
    @Param('plant') plant: number,
    @Res() response: Response,
  ): Promise<Response> {
    const result = await this.adminService.fetchResourceDetailsByPlant(plant);
    return response.status(HttpStatus.OK).json(result);
  }

  @Post('/update-resource')
  @UseFilters(MesGenericErrorFilter)
  @ApiOperation({ summary: 'Update an existing resource' })
  @ApiBody({
    description: ' details of resource to be updated',
    type: UpdateResourceParameterDto,
  })
  @ApiResponse({
    description: 'The updated resource',
    status: 200,
    type: ResourceDto,
  })
  @ApiResponse({ description: 'resource not found.', status: 404 })
  public async updateResource(
    @Body() resource: UpdateResourceParameterDto,
    @Res() response: Response,
  ): Promise<Response> {
    const updatedResource = await this.adminService.updateResource(resource);
    return response.status(200).json(updatedResource);
  }

  @Delete('/delete-resource/:plant/:resourceId')
  @ApiOperation({ summary: 'delete an existing resource' })
  @ApiParam({
    description: 'The plant ID for which resource  are to be deleted',
    name: 'plant',
    type: Number,
  })
  @ApiParam({
    description: 'The resouce ID for which resource  to be deleted',
    name: 'resourceId',
    type: String,
  })
  @ApiResponse({
    description: 'The deleted resource',
    status: 200,
    type: ResourceDto,
  })
  @ApiResponse({ description: 'resource not found.', status: 404 })
  public async deleteResource(
    @Param('plant') plant: number,
    @Param('resourceId') resourceId: string,
    @Res() response: Response,
  ): Promise<Response> {
    try {
      const deleteResource = await this.adminService.deleteResource(
        plant,
        resourceId,
      );
