// Create mocks for DaprClient
jest.mock('dapr-client', () => {
  // Mock implementation
  const mockInvoke = jest.fn();
  const mockImplementation = jest.fn().mockImplementation(() => ({
    invoker: {
      invoke: mockInvoke,
    },
  }));

  // Create a properly named mock and provide access to it
  const mockObject = {
    // Using a getter with proper return type and camelCase name
    get daprClient(): jest.Mock {
      return mockImplementation;
    },
  };

  // Create a proxy to intercept requests for DaprClient
  return new Proxy(mockObject, {
    get(target, property): unknown {
      // When code asks for DaprClient, return the mockImplementation
      if (property === 'DaprClient') {
        return mockImplementation;
      }
      return target[property as keyof typeof target];
    },
  });
});

