import { HttpMethod } from '@dapr/dapr';
import {
  Injectable,
  InternalServerErrorException,
  Logger,
  NotFoundException,
} from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { ResourceWithMesInfoResponseDto } from './dto/resource-with-mes-info.response.dto';
import { ResourceDto } from './dto/resource.dto';
import { StorageLocationResponseDTO } from './dto/storage-location.response.dto';
import { UpdateEwmWipDTO } from './dto/update-ewm-dto';
import { UpdateResourceParameterDto } from './dto/update-resource-parameter.dto';
import { UpdateWorkcenter } from './dto/update-workcenter.dto';
import { WorkcenterPlantDto } from './dto/workcenter-plant.dto';
import { WorkcenterResponse } from './dto/workcenter-response.dto';
import { PlantConfigOrder } from './interfaces/plant-config-order.model';
import { PlantConfigShipment } from './interfaces/plant-config-shipment.model';
import { PlanHierarchy } from './interfaces/plant-hierarchy.model';
import { PlantWithConfig } from './interfaces/plant-with-config.model';
import { Plant } from './interfaces/plant.model';
import { ResourceManagementService } from './resource-management/resource-management.service';
import { MaterialRequestDto } from '@/admin/dto/material-request.dto';
import { MaterialWithDtlResponseDto } from '@/admin/dto/material-with-dtl-response.dto';
import { WorkcentersDTO } from '@/admin/dto/workcenters.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class AdminService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(AdminService.name);

  public constructor(
    private readonly daprConfigService: DaprConfigService,
    private readonly resourceManagementService: ResourceManagementService,
  ) {
    this.daprClient = new DaprClient();
  }

  public async fetchPlants(): Promise<Array<Plant>> {
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/Plants`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.GET,
      undefined,
      options,
    );
    if (response) {
      return response as Array<Plant>;
    }
    throw new Error('Invalid response from fetchPlants');
  }

  // Fetch Plant by ID
  public async fetchPlantById(id: number): Promise<Plant> {
    const token = `Bearer ${process.env.TOKEN}`;
    const options = { headers: { authorization: token } };
    const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
    const serviceMethod = `plant/getPlantById/${id}`;
    const response = await this.daprClient.invoker.invoke(
      serviceAppId,
      serviceMethod,
      HttpMethod.GET,
      undefined,
      options,
    );
    if (response) {
      return response as Plant;
    }
    throw new Error('Invalid response from fetchPlantById');
  }

  public async fetchPlantConfigOrder(
    plantId: number,
  ): Promise<PlantConfigOrder | null> {
    const serviceAppId = this.daprConfigService.orderApiAppId;
    const serviceMethod = `plant-config-order/${plantId}`;
    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      );

      // Check if the response is valid
      if (response) {
        return response as PlantConfigOrder;
      }
      return null; // Return null if no config is found
    } catch {
      // Log the error but return null to avoid throwing
      return null; // Return null instead of throwing the error
    }
  }

  public async fetchPlantWithConfig(id: number): Promise<PlantWithConfig> {
    // Fetch plant configuration, but allow null as a valid result
    const configOrder = await this.fetchPlantConfigOrder(id);
    // Fetch plant details (will throw if not found)
    const plant = await this.fetchPlantById(id);
    // Merge both into one object and return
    const plantWithConfig: PlantWithConfig = {
      aggrTimeLvlBoard: configOrder?.aggrTimeLvlBoard ?? 60,
      alertCreation: configOrder?.alertCreation ?? 'MANUAL',
      downtimeTicketReclassificationThreshold:
        plant.downtimeTicketReclassificationThreshold,
      ewmFlow: plant.ewmFlow,
      languageCode: plant.languageCode ?? 'EN',
      mleanLink: plant.mleanLink,
      offsetTo: configOrder?.offsetTo ?? 220,
      plantDesc: plant.plantDesc,
      plantId: plant.plantId,
      secondaryLanguageCode: plant.secondaryLanguageCode,
      sid: plant.sid,
      timezone: plant.timezone,
      toleranceValueWk: configOrder?.toleranceValueWk ?? 60,
      voiceToActEnabled: plant.voiceToActEnabled ?? false,
    };

    return plantWithConfig;
  }

