    try {
      const serviceAppId = this.daprConfigService.plantHierarchyApiAppId;
      const serviceMethod = `resource/${plant}`;
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      );
      if (response) {
        return response as Array<string>;
      }
      return [];
    } catch (error) {
      this.logger.error(
        `failed to fetch resource by  plant : ${plant}, ${error}`,
      );
      return [];
    }
  }

