  private async getUserAttributes(
    userId: string,
  ): Promise<Record<string, string>> {
    const daprClient = new DaprClient();
    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      const userAttributesResponse = (await daprClient.invoker.invoke(
        this.daprConfigService.umeApiAppId,
        `user-attribute-mapping/${userId}`,
        HttpMethod.GET,
        undefined,
        options,
      )) as Array<{ userAttributeName: string; value: string }>;

      const result: Record<string, string> = {};
      for (const item of userAttributesResponse) {
        result[item.userAttributeName] = item.value;
      }
      return result;
    } catch (error) {
      this.logger.error('Error getting user attributes:', error);
      throw error;
    }
  }

  private async getRestrictedHierarchy(
    plantId: string,
    attributes: Record<string, string>,
  ): Promise<Array<PlanHierarchy>> {
    const daprClient = new DaprClient();
    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      const response = (await daprClient.invoker.invoke(
        this.daprConfigService.plantHierarchyApiAppId,
        `plant/getRestrictedHierarchy/${plantId}`,
        HttpMethod.POST,
        attributes,
        options,
      )) as Array<PlanHierarchy>;

      return response;
    } catch (error) {
      this.logger.error('Error fetching hierarchy:', error);
      throw error;
    }
  }

  public async getHierarchy(
    userId: string,
  ): Promise<Array<PlanHierarchy> | undefined> {
    try {
      const attributes = await this.getUserAttributes(userId);
      const hierarchy = await this.getRestrictedHierarchy(
        attributes.plant,
        attributes,
      );
      return hierarchy;
    } catch (error) {
      this.logger.error('Error getting restricted hierarchy:', error);
      throw error;
    }
  }

