    type: UpdateBOMComponentsResponseDTO,
  })
  @ApiResponse({
    status: HttpStatus.NOT_FOUND,
    description: 'Component not found',
  })
  @ApiResponse({
    status: HttpStatus.INTERNAL_SERVER_ERROR,
    description: 'Internal server error',
  })
  public async updateBOMComponentsById(
    @Body() updateDto: UpdateBOMComponentsRequestDTO,
  ): Promise<UpdateBOMComponentsResponseDTO> {
    return this.bomService.updateBOMComponentsById(updateDto);
  }

  @Post('get-boms')
  @ApiOperation({
    summary: 'Retrieve a valid BOM for a specific material',
    description:
      'Find the valid BOM for a material at a specific date, with optional component inclusion',
