import { HttpMethod } from '@dapr/dapr';
import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import {
  BOMResponseDTO,
  GetBOMQueryParametersDTO,
  UpdateBOMComponentsRequestDTO,
  UpdateBOMComponentsResponseDTO,
  GetBOMsByBomIdDTO,
  GetBOMsResponseDTO,
} from './dto/bom.dto';
import { BOMComponentResponseDTO } from './dto/response/bom-component-response.dto';
import { BOMSubComponentResponseDTO } from './dto/response/bom-sub-component-response.dto';
import { MaterialDtlResponseDTO } from './dto/response/material-dtl-response.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

@Injectable()
export class BOMService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(BOMService.name);

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  /**
   * Retrieves a BOM with all its components and subcomponents
   * @param queryParameters Parameters to filter the BOM, including materialId, plant, validityDate, erpBomId, and includeComponents
   * @returns The BOM with its components enriched with procurement type
   */
  public async getBOMWithComponents(
    queryParameters: GetBOMQueryParametersDTO,
  ): Promise<BOMResponseDTO> {
    try {
      const serviceAppId = this.daprConfigService.masterApiAppId;
      const serviceMethod = `boms/get-boms`;
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.POST,
        queryParameters,
      );

      if (!response) {
        throw new NotFoundException('BOM not found');
      }

      const bomResponse = response as BOMResponseDTO;

      // Enrich components with procurement type from order-api
      if (bomResponse.components && bomResponse.components.length > 0) {
        try {
          await this.enrichComponentsWithProcurementType(
            bomResponse.components,
            queryParameters.plant,
          );
        } catch (enrichError) {
          this.logger.warn(
            `Components enrichment failed (plant=${queryParameters.plant}): ${enrichError instanceof Error ? enrichError.message : enrichError}`,
          );
          // We intentionally do not rethrow to still return the raw BOM response
        }
      }

      return bomResponse;
    } catch (error) {
      this.logger.error(`Error retrieving BOM: ${error.message}`, error.stack);
      throw error;
    }
  }

  /**
   * Updates BOM components by their IDs
   * @param updateDto The update request containing component IDs and properties to update
   * @returns Response indicating success or failure
   */
  public async updateBOMComponentsById(
    updateDto: UpdateBOMComponentsRequestDTO,
  ): Promise<UpdateBOMComponentsResponseDTO> {
    try {
      const serviceAppId = this.daprConfigService.masterApiAppId;
      const serviceMethod = `boms/update-components`;

      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.PUT,
        updateDto,
      );

      if (!response) {
        throw new Error('Failed to update BOM components');
      }

      return response as UpdateBOMComponentsResponseDTO;
    } catch (error) {
      this.logger.error(
        `Error updating BOM components: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Retrieves a list of BOMs by BOM ID that are valid at a specific date
   * @param erpBomId The ERP BOM ID to search for
   * @param plant The plant ID where the BOM is used
   * @param validityDate Optional date to check validity against
   * @returns List of BOMs that match the criteria
   */
  public async getBOMsByBomId(
    erpBomId: string,
    plant: number,
    validityDate?: Date,
  ): Promise<GetBOMsResponseDTO> {
    try {
      const serviceAppId = this.daprConfigService.masterApiAppId;
      const serviceMethod = `boms/get-erp-boms`;

      const requestBody: GetBOMsByBomIdDTO = {
        erpBomId,
        plant,
        validityDate,
      };
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.POST,
        requestBody,
      );
      if (!response) {
        throw new NotFoundException('BOMs not found');
      }

      return response as GetBOMsResponseDTO;
    } catch (error) {
      this.logger.error(
        `Error retrieving BOMs by BOM ID: ${error.message}`,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Enriches components and their sub-components with procurement type from order-api.
   * Each component's own material ID (component.component) is used to fetch data.
   * @param components The components to enrich
   * @param plant The plant ID
   */
  private async enrichComponentsWithProcurementType(
    components: Array<BOMComponentResponseDTO>,
    plant: number,
  ): Promise<void> {
    // Simple in-memory cache for this enrichment run to avoid duplicate calls
    const materialCache = new Map<string, MaterialDtlResponseDTO | null>();

    const getDtl = async (
      matId: string,
    ): Promise<MaterialDtlResponseDTO | null> => {
      const cacheKey = `${plant}:${matId}`;
      if (materialCache.has(cacheKey)) {
        return materialCache.get(cacheKey) ?? null;
      }
      const dtl = await this.getMaterialDtlById(plant, matId);
      materialCache.set(cacheKey, dtl);
      return dtl;
    };
    try {
      await Promise.all(
        components.map(async (component) => {
          // Enrich the main component
          try {
            await this.enrichSingleComponentWithProcurementType(
              component,
              plant,
              getDtl,
            );
          } catch (error) {
            this.logger.warn(
              `Failed to enrich main component ${component.component} in plant ${plant}: ${error instanceof Error ? error.message : error}`,
            );
          }

          // Enrich sub-components if they exist
          if (component.subComponents && component.subComponents.length > 0) {
            await Promise.all(
              component.subComponents.map(async (subComponent) => {
                try {
                  await this.enrichSingleComponentWithProcurementType(
                    subComponent,
                    plant,
                    getDtl,
                  );
                } catch (error) {
                  this.logger.warn(
                    `Failed to enrich sub-component ${subComponent.component} in plant ${plant}: ${error instanceof Error ? error.message : error}`,
                  );
                }
              }),
            );
          }
        }),
      );
    } catch (error) {
      // Global safeguard: shouldn't usually happen because each component is already protected
      this.logger.error(
        `Unexpected error during components enrichment (plant=${plant}): ${error instanceof Error ? error.message : error}`,
        error instanceof Error ? error.stack : undefined,
      );
    }
  }

  /**
   * Enriches a single component with procurement type from order-api using its own material ID.
   * @param component The component to enrich
   * @param plant The plant ID
   * @param getDtl Cached fetcher function
   */
  private async enrichSingleComponentWithProcurementType(
    component: BOMSubComponentResponseDTO,
    plant: number,
    getDtl: (materialId: string) => Promise<MaterialDtlResponseDTO | null>,
  ): Promise<void> {
    try {
      const materialId = component.component; // Material ID of this component // Material ID of this component
      if (!materialId) {
        return;
      }
      const materialDtl = await getDtl(materialId);
      if (materialDtl?.procurementType) {
        // Assign on a shallow clone to avoid param mutation lint issues and ensure enumerability
        const enriched: BOMSubComponentResponseDTO & {
          procurementType?: string;
        } = {
          ...component,
          procurementType: materialDtl.procurementType,
        };
        Object.assign(component, enriched);
      }
    } catch (error) {
      this.logger.warn(
        `Failed to get procurement type for component ${component.component} in plant ${plant}: ${error instanceof Error ? error.message : error}`,
      );
    }
  }

  /**
   * Retrieves material details by plant and material ID from order-api
   * @param plant The plant ID
   * @param materialId The material ID
   * @returns Material details including procurement type
   */
  private async getMaterialDtlById(
    plant: number,
    materialId: string,
  ): Promise<MaterialDtlResponseDTO | null> {
    try {
      const serviceAppId = this.daprConfigService.orderApiAppId;
      const serviceMethod = `material-dtl/getMaterialDtlById/${plant}/${materialId}`;
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      );
      return response as MaterialDtlResponseDTO;
    } catch (error) {
      this.logger.error(
        `Error retrieving material details for ${materialId} in plant ${plant}: ${error.message}`,
        error.stack,
      );
      return null;
    }
  }
}

