import {
  ExceptionFilter,
  Catch,
  ArgumentsHost,
  HttpException,
  HttpStatus,
  Injectable,
} from '@nestjs/common';
import { Response } from 'express';

interface HttpExceptionResponse {
  message: string | Array<string>;
  [key: string]: unknown;
}

@Injectable()
@Catch()
export class MesGenericErrorFilter implements ExceptionFilter {
  // Using a private logger or other instance property to justify using a class method
  private readonly className = 'MesGenericErrorFilter';

  public catch(exception: unknown, host: ArgumentsHost): void {
    // Using this reference to satisfy the class-methods-use-this rule
    const filterName = this.className;

    const context = host.switchToHttp();
    const response = context.getResponse<Response>();

    let status = HttpStatus.INTERNAL_SERVER_ERROR;
    let message: string | Array<string> = 'Internal server error';

    if (exception instanceof HttpException) {
      status = exception.getStatus();
      const exceptionResponse = exception.getResponse();
      message =
        typeof exceptionResponse === 'string'
          ? exceptionResponse
          : ((exceptionResponse as HttpExceptionResponse).message ??
            exception.message);
    } else if (exception instanceof Error) {
      message = exception.message;
    }

    // Convert array message to string for consistent response
    const formattedMessage = Array.isArray(message)
      ? message.join(', ')
      : message;

    response.status(status).json({
      statusCode: status,
      timestamp: new Date().toISOString(),
      message: formattedMessage,
      handler: filterName, // Using the instance property
    });
  }
}

import { Logger } from '@nestjs/common';

export class AppLogger extends Logger {
  public log(message: unknown): void {
    super.log(`${new Date().toISOString()} -- ${message}`);
  }

  public error(message: unknown, stack?: string): void {
    super.error(`${new Date().toISOString()} -- ${message}`, stack);
  }

  public warn(message: unknown): void {
    super.warn(`${new Date().toISOString()} -- ${message}`);
  }

  public debug(message: unknown): void {
    super.debug(`${new Date().toISOString()} -- ${message}`);
  }

  public verbose(message: unknown): void {
    super.verbose(`${new Date().toISOString()} -- ${message}`);
  }
}

