@Module({
  exports: [CosmosDatabaseService],
  imports: [ConfigModule, CosmosDatabaseConfigModule],
  providers: [CosmosDatabaseService],
})
export class CosmosDatabaseModule {}

import { randomUUID } from 'node:crypto';
import { CosmosClient } from '@azure/cosmos';
import { DefaultAzureCredential } from '@azure/identity';
import { Injectable, Logger } from '@nestjs/common';
import { CreateTemplateDto } from './dto/create-template.dto';
import { TemplateDto } from './dto/template.dto';
import { CosmosDatabaseConfigService } from '@/config/cosmos-db/cosmos.database.service';

@Injectable()
export class CosmosDatabaseService {
  private static generateTemplateKey(): string {
    // Generate a unique template key using UUID
    return `TPL-${randomUUID()}`;
  }

  private readonly client: CosmosClient;

  private readonly database;

  private readonly container;

  private readonly logger = new Logger(CosmosDatabaseService.name);

  public constructor(
    private readonly cosmosDatabasebService: CosmosDatabaseConfigService,
  ) {
    // Create DefaultAzureCredential with the user-assigned managed identity's Client ID
    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosDatabasebService.cosmosDbEndpoint,
    });

    this.database = this.client.database(
      this.cosmosDatabasebService.cosmosDbDatabase,
    );
    this.container = this.database.container(
      this.cosmosDatabasebService.cosmosDbPageBuilder,
    );
  }

  public async upsertTemplate(
    createTemplateDto: CreateTemplateDto,
  ): Promise<TemplateDto | undefined> {
    try {
      // Auto-generate templateId if not provided
      const templateId =
        createTemplateDto.id ?? CosmosDatabaseService.generateTemplateKey();
      const now = new Date().toISOString();

      // Check if template exists
      const existingTemplate = await this.getTemplate(templateId);

      // Check for existing published templates with the same scope and remove those scopes
      if (
        createTemplateDto.status === 'published' &&
        createTemplateDto.scopeList &&
        createTemplateDto.scopeList.length > 0
      ) {
        // For each scope in the new template, get existing published templates
        const scopeTemplatePromises = createTemplateDto.scopeList.map(
          async (scope) => {
            const template = await this.getTemplatesByScope(
              createTemplateDto.plant,
              scope.scopeType,
              scope.scopeValue,
            );
            return { scope, template };
          },
        );

        const scopeTemplates = await Promise.all(scopeTemplatePromises);

        // Group by template ID to handle multiple matching scopes
        const templateUpdates = new Map<
          string,
          {
            template: TemplateDto;
            scopesToRemove: Array<{ scopeType: string; scopeValue: string }>;
          }
        >();

        for (const { scope, template } of scopeTemplates) {
          if (
            template?.id &&
            template.id !== templateId &&
            template.status === 'published'
          ) {
            const existingUpdate = templateUpdates.get(template.id);
            if (existingUpdate) {
              existingUpdate.scopesToRemove.push(scope);
            } else {
              templateUpdates.set(template.id, {
                template,
                scopesToRemove: [scope],
              });
            }
          }
        }

        // Update each template by removing the matching scopes
        const upsertPromises = [...templateUpdates.values()].map(
          ({ template, scopesToRemove }) => {
            const updatedScopeList = template.scopeList?.filter(
              (existingScope) =>
                !scopesToRemove.some(
                  (scopeToRemove) =>
                    existingScope.scopeType === scopeToRemove.scopeType &&
                    existingScope.scopeValue === scopeToRemove.scopeValue,
                ),
            );

            const updatedTemplate = {
              ...template,
              scopeList: updatedScopeList,
              updatedAt: now,
              updatedBy: createTemplateDto.createdBy,
            };
            return this.container.items.upsert(updatedTemplate).then(() => {});
          },
        );

        await Promise.all(upsertPromises);
      }

      const template: TemplateDto = {
        createdAt: existingTemplate?.createdAt ?? now,
        createdBy: existingTemplate?.createdBy ?? createTemplateDto.createdBy,
        default: createTemplateDto.default ?? false,
        devices: createTemplateDto.devices,
        id: templateId,
        label: createTemplateDto.label,
        plant: createTemplateDto.plant,
        scopeList: createTemplateDto.scopeList,
        screens: createTemplateDto.screens,
        status: createTemplateDto.status ?? 'draft',
        updatedAt: now,
        updatedBy: createTemplateDto.createdBy,
      };

      const { resource } = await this.container.items.upsert(template);
      return resource as unknown as TemplateDto;
    } catch (error) {
      this.logger.error(
        `Error upserting template in Cosmos DB: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  public async getTemplate(
    templateId: string,
  ): Promise<TemplateDto | undefined> {
    try {
      const querySpec = {
        parameters: [{ name: '@id', value: templateId }],
        query: `SELECT * FROM c WHERE c.id = @id`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();
      if (resources.length > 0) {
        return resources[0] as TemplateDto;
      }
      return undefined;
    } catch (error) {
      this.logger.error(
        `Error retrieving template from Cosmos DB: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  public async getTemplatesByPlant(
    plantId: number,
  ): Promise<Array<TemplateDto> | undefined> {
    try {
      const querySpec = {
        parameters: [{ name: '@plant', value: plantId }],
        query: `SELECT * FROM c WHERE c.plant = @plant OR c.plant = 0`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      const sortedResources = [...resources].sort((a, b) => {
        const isDefaultA = a.default ? 1 : 0;
        const isDefaultB = b.default ? 1 : 0;

        if (isDefaultA !== isDefaultB) {
          return isDefaultB - isDefaultA;
        }

        const tsA = typeof a['_ts'] === 'number' ? a['_ts'] : 0;
        const tsB = typeof b['_ts'] === 'number' ? b['_ts'] : 0;
        return tsB - tsA;
      });

      return sortedResources as Array<TemplateDto>;
    } catch (error) {
      this.logger.error(
        `Error retrieving templates by plant from Cosmos DB: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  public async deleteTemplate(templateId: string): Promise<void> {
    try {
      // Get the template to retrieve the partition key (plant)
      const template = await this.getTemplate(templateId);

      if (!template) {
        this.logger.error(`Template with ID ${templateId} not found`);
        return;
      }

      if (template.plant === undefined || template.plant === null) {
        this.logger.error(
          `Template with ID ${templateId} has no plant partition key`,
        );
        return;
      }

      await this.container.item(templateId, template.plant).delete();
    } catch (error) {
      this.logger.error(
        `Error deleting template from Cosmos DB: ${error.message}`,
        error.stack,
      );
    }
  }

  public async getTemplatesByScope(
    plantId: number,
    scopeType: string,
    scopeValue: string,
    screenId?: number,
  ): Promise<TemplateDto | undefined> {
    try {
      const hasScreenFilter = screenId !== undefined;
      const querySpec = {
        parameters: [
          { name: '@plant', value: plantId },
          { name: '@scopeType', value: scopeType },
          { name: '@scopeValue', value: scopeValue },
          { name: '@status', value: 'published' },
          ...(hasScreenFilter ? [{ name: '@screenId', value: screenId }] : []),
        ],
        query: `
SELECT TOP 1 *
FROM c
WHERE c.plant = @plant
AND c.status = @status
AND EXISTS(
 SELECT VALUE scope
 FROM scope IN c.scopeList
 WHERE UPPER(scope.scopeType) = UPPER(@scopeType)
 AND UPPER(scope.scopeValue) = UPPER(@scopeValue)
)
${
  hasScreenFilter
    ? `AND EXISTS(
 SELECT VALUE screen
 FROM screen IN c.screens
 WHERE screen.screenId = @screenId
)`
    : ''
}
`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      if (resources.length > 0) {
        return resources[0] as TemplateDto;
      }
      return undefined;
    } catch (error) {
      this.logger.error(
        `Error retrieving template by scope from Cosmos DB: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  public async getDefaultTemplate(
    plantId: number,
    screenId?: number,
  ): Promise<TemplateDto | undefined> {
    try {
      const hasScreenFilter = screenId !== undefined;
      const querySpec = {
        parameters: [
          { name: '@plant', value: plantId },
          { name: '@default', value: true },
          ...(hasScreenFilter ? [{ name: '@screenId', value: screenId }] : []),
        ],
        query: `SELECT * FROM c WHERE c.plant = @plant AND c.default = @default${
          hasScreenFilter
            ? ` AND EXISTS(
 SELECT VALUE screen
 FROM screen IN c.screens
 WHERE screen.screenId = @screenId
)`
            : ''
        }`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      if (resources.length > 0) {
        return resources[0] as TemplateDto;
      }
      return undefined;
    } catch (error) {
      this.logger.error(
        `Error retrieving default template from Cosmos DB: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }
}

