import { Injectable, Logger } from '@nestjs/common';
import { DaprClient, HttpMethod } from 'dapr-client';
import { AppLogger } from 'src/common/logger/app-logger';
import { DaprConfigService } from 'src/config/dapr/dapr-config.service';
import { NpsConfigRoleDto } from './nps-config-role.dto';

@Injectable()
export class NpsConfigRoleService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(NpsConfigRoleService.name);

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  public async getNpsConfigRoleById(
    npsId: number,
  ): Promise<NpsConfigRoleDto | null> {
    const serviceAppId = this.daprConfigService.umeApiAppId;
    const serviceMethod = `nps-config-role/by-config/${npsId}`;

    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      const response = (await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
        undefined,
        options,
      )) as NpsConfigRoleDto;
      return response;
    } catch (error) {
      AppLogger.error(
        `Error invoking Dapr service ${serviceAppId}/${serviceMethod}:`,
        error,
      );
      return null;
    }
  }
}

