import { Injectable, Logger, NotFoundException } from '@nestjs/common';
import { LayoutApi } from '@/apis/apis';
import { ComponentDto } from '@/apis/dto/component.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';
import { CosmosDatabaseService } from '@/cosmos-db/cosmos.database.service';
import { CreateTemplateDto } from '@/cosmos-db/dto/create-template.dto';
import { TemplateDto } from '@/cosmos-db/dto/template.dto';

@Injectable()
export class PageBuilderService {
  private readonly logger = new Logger(PageBuilderService.name);

  private readonly layoutApi = new LayoutApi();

  public constructor(
    private readonly cosmosDatabaseService: CosmosDatabaseService,
    private readonly daprConfigService: DaprConfigService,
  ) {}

  public async upsertTemplate(
    createTemplateDto: CreateTemplateDto,
  ): Promise<TemplateDto | undefined> {
    try {
      await this.enrichLayoutConstraints(createTemplateDto);
      await this.enrichComponentConstraints(createTemplateDto);
      return this.cosmosDatabaseService.upsertTemplate(createTemplateDto);
    } catch (error) {
      this.logger.error(
        `Failed to upsert template: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  private async enrichLayoutConstraints(
    createTemplateDto: CreateTemplateDto,
  ): Promise<void> {
    const deviceConfigs = [
      createTemplateDto.devices?.desktop,
      createTemplateDto.devices?.mobile,
      createTemplateDto.devices?.tablet,
    ].filter((deviceConfig): deviceConfig is NonNullable<typeof deviceConfig> =>
      Boolean(deviceConfig?.layout?.id),
    );

    if (deviceConfigs.length === 0) {
      return;
    }

    // Extract and concatenate screen names from createTemplateDto.screens
    const screenNames = createTemplateDto.screens
      ?.map((screen) => screen.screenName)
      .filter(Boolean)
      .join(';');

    if (!screenNames) {
      this.logger.warn(
        'No screen names found in template, skipping layout enrichment',
      );
      return;
    }

    const token = process.env.TOKEN;
    const layoutCache = new Map<
      string,
      ReturnType<LayoutApi['findLayoutByScreenId']>
    >();

    const getLayoutByScreenNames = (
      screenId: string,
    ): ReturnType<LayoutApi['findLayoutByScreenId']> => {
      const cachedLayoutPromise = layoutCache.get(screenId);

      if (cachedLayoutPromise) {
        return cachedLayoutPromise;
      }

      const layoutPromise = this.layoutApi.findLayoutByScreenId(
        this.daprConfigService.umeApiAppId,
        screenId,
        token,
      );

      layoutCache.set(screenId, layoutPromise);
      return layoutPromise;
    };

    await Promise.all(
      deviceConfigs.map(async (deviceConfig) => {
        const currentLayout = deviceConfig.layout;

        const layoutFromApi = await getLayoutByScreenNames(screenNames);

        if (!layoutFromApi) {
          this.logger.warn(
            `Layout not found for screens "${screenNames}" while enriching template`,
          );
        }

        currentLayout.minSection = layoutFromApi?.minSection || 1;
        currentLayout.maxSection = layoutFromApi?.maxSection || 4;

        // Map height and width from API response
        if (layoutFromApi?.height !== undefined) {
          currentLayout.height = layoutFromApi?.height;
        }
        if (layoutFromApi?.width !== undefined) {
          currentLayout.width = layoutFromApi?.width;
        }

        for (const section of currentLayout.sections ?? []) {
          section.minWidget = layoutFromApi?.minWidget || 1;
          section.maxWidget = layoutFromApi?.maxWidget || 9;
        }
      }),
    );
  }

  private async enrichComponentConstraints(
    createTemplateDto: CreateTemplateDto,
  ): Promise<void> {
    const deviceConfigs = [
      createTemplateDto.devices?.desktop,
      createTemplateDto.devices?.mobile,
      createTemplateDto.devices?.tablet,
    ].filter((deviceConfig): deviceConfig is NonNullable<typeof deviceConfig> =>
      Boolean(deviceConfig?.layout),
    );

    if (deviceConfigs.length === 0) {
      return;
    }

    const token = process.env.TOKEN;
    const componentCache = new Map<
      number,
      ReturnType<LayoutApi['findComponentById']>
    >();

    const getComponentById = (
      componentId: string,
    ): ReturnType<LayoutApi['findComponentById']> => {
      const cachedComponentPromise = componentCache.get(Number(componentId));

      if (cachedComponentPromise) {
        return cachedComponentPromise;
      }

      const componentPromise = this.layoutApi.findComponentById(
        this.daprConfigService.umeApiAppId,
        componentId,
        token,
      );

      componentCache.set(Number(componentId), componentPromise);
      return componentPromise;
    };

    const enrichmentPromises = deviceConfigs.flatMap((deviceConfig) => {
      const sections = deviceConfig.layout?.sections ?? [];

      return sections.flatMap((section) => {
        const widgets = section.widgets ?? [];

        return widgets
          .filter((widget) => widget.component)
          .map(async (widget) => {
            const currentComponent = widget.component;
            const componentId = currentComponent.code;

            const componentFromApi = await getComponentById(componentId);

            if (!componentFromApi) {
              this.logger.warn(
                `Component ${componentId} not found while enriching template`,
              );
              return;
            }

            // Map showLabel from API response
            if (componentFromApi.showLabel !== undefined) {
              currentComponent.showLabel = Boolean(componentFromApi.showLabel);
            }
          });
      });
    });

    await Promise.all(enrichmentPromises);
  }

  public async getTemplate(
    templateId: string,
  ): Promise<TemplateDto | undefined> {
    try {
      const template = await this.cosmosDatabaseService.getTemplate(templateId);

      if (!template) {
        throw new NotFoundException(`Template with ID ${templateId} not found`);
      }

      return template;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve template: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  public async getTemplatesByPlant(
    plantId: number,
  ): Promise<Array<TemplateDto> | undefined> {
    try {
      return this.cosmosDatabaseService.getTemplatesByPlant(plantId);
    } catch (error) {
      this.logger.error(
        `Failed to retrieve templates for plant: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  public async getTemplatesByScope(
    plantId: number,
    scopeType: string,
    scopeValue: string,
    screenId?: number,
  ): Promise<TemplateDto | undefined> {
    try {
      return this.cosmosDatabaseService.getTemplatesByScope(
        plantId,
        scopeType,
        scopeValue,
        screenId,
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve template by scope: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  public async deleteTemplate(templateId: string): Promise<void> {
    try {
      await this.cosmosDatabaseService.deleteTemplate(templateId);
    } catch (error) {
      this.logger.error(
        `Failed to delete template: ${error.message}`,
        error.stack,
      );
    }
  }

  public async getDefaultTemplate(
    plantId: number,
    screenId?: number,
  ): Promise<TemplateDto | undefined> {
    try {
      const template = await this.cosmosDatabaseService.getDefaultTemplate(
        plantId,
        screenId,
      );

      if (!template) {
        throw new NotFoundException(
          `No default template found for plant ${plantId}${
            screenId === undefined ? '' : ` and screen ${screenId}`
          }`,
        );
      }

      return template;
    } catch (error) {
      this.logger.error(
        `Failed to retrieve default template: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }

  public async getAllComponents(): Promise<Array<ComponentDto> | undefined> {
    try {
      const token = process.env.TOKEN;
      return this.layoutApi.findAllComponents(
        this.daprConfigService.umeApiAppId,
        token,
      );
    } catch (error) {
      this.logger.error(
        `Failed to retrieve components: ${error.message}`,
        error.stack,
      );
      return undefined;
    }
  }
}

