@Injectable()
export class PermissionService {
  private readonly daprClient: DaprClient;

  private readonly logger = new Logger(PermissionService.name);

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  public async getAllRolesByAppName(
    appName: string,
  ): Promise<Array<{ roleId: number; roleName: string }>> {
    const serviceAppId = this.daprConfigService.umeApiAppId;
    const serviceMethod = `permissions/roles/${appName}`;

    try {
      const token = `Bearer ${process.env.TOKEN}`;
      const options = { headers: { authorization: token } };
      const response = (await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
        undefined,
        options,
      )) as Array<{ roleId: number; roleName: string }>;
      return response;
    } catch (error) {
      AppLogger.error(
        `Error invoking Dapr service ${serviceAppId}/${serviceMethod}:`,
        error,
      );
      return [];
    }
  }
}

