import { HttpMethod } from '@dapr/dapr';
import { Injectable, InternalServerErrorException } from '@nestjs/common';
import { DaprClient } from 'dapr-client';
import { OperationType } from 'dapr-client/types/Operation.type';
import { AssignMaterialDto } from './dto/assign-material.dto';
import { CreateOperationDto } from './dto/create-operation.dto';
import { CreateRoutingDto } from './dto/create-routing.dto';
import { UpdateOperationDto } from './dto/update-operation.dto';
import { UpdateRoutingDto } from './dto/update-routing.dto';
import { DaprConfigService } from '@/config/dapr/dapr-config.service';

// Local material typings (entities live in other services/repositories).
// MaterialDTL represents master material details (material + plant etc.).
// MaterialDtl represents assigned routing material (may include routingId).
export interface MaterialDTL {
  materialId: string;
  plant?: number;
  groupingAGV?: number;
  kitmat?: boolean;
  prodstrat?: string;
  sebango?: string;
  autoTransfer?: string;
  bomNumber?: string;
}

export interface MaterialDtl {
  materialId: string;
  plant?: number;
  routingId?: number;
}

/**
 * Routing service implemented as a thin proxy to underlying microservices using Dapr service invocation.
 * All persistence and business rules are delegated to the appropriate APIs. This keeps this service
 * consistent with other services in the repo which use Dapr for cross-service calls.
 */
@Injectable()
export class RoutingsService {
  private readonly daprClient: DaprClient;

  public constructor(private readonly daprConfigService: DaprConfigService) {
    this.daprClient = new DaprClient();
  }

  /**
   * Fetch combined assigned/available payload from order-management API.
   * The endpoint may return either an array (assigned list) or an object { assigned, available }.
   * @param routingId - id of the routing to retrieve materials for
   * @param plant - plant id used to filter the materials
   * @returns a promise that resolves to the raw response from the order-management API; may be an array (assigned list) or an object containing assigned and available arrays
   */
  private async fetchroutingMaterials(
    routingId: number,
    plant: number,
  ): Promise<unknown> {
    const serviceAppId = this.daprConfigService.orderManagementApiAppId;
    const method = `routings/${routingId}/materials?plant=${encodeURIComponent(String(plant))}`;
    const resp = await this.daprClient.invoker.invoke(
      serviceAppId,
      method,
      HttpMethod.GET,
    );
    return resp;
  }

  /**
   * Fetch master materials for a plant from master API and normalize to MaterialDTL[]
   * @param plant - plant id to fetch master materials for
   * @returns Promise resolving to an array of master material details (MaterialDTL[]). Returns an empty array on failure.
   */
  private async fetchMasterMaterials(
    plant: number,
  ): Promise<Array<MaterialDTL>> {
    const serviceAppId = this.daprConfigService.masterApiAppId;
    const method = `material/getAllMaterial/${plant}`;
    try {
      const resp = await this.daprClient.invoker.invoke(
        serviceAppId,
        method,
        HttpMethod.GET,
      );

      if (Array.isArray(resp)) {
        return resp as Array<MaterialDTL>;
      }
      if (resp) {
        return [resp as MaterialDTL];
      }
      return [];
    } catch {
      // On master failure return empty list (graceful)
      return [];
    }
  }

  // Retrieve all routings by invoking the order-management-api
  public async findAll(plant: number): Promise<unknown> {
    const serviceAppId = this.daprConfigService.orderManagementApiAppId;
    const serviceMethod = `routings?plant=${encodeURIComponent(String(plant))}`;
    try {
      const response = await this.daprClient.invoker.invoke(
        serviceAppId,
        serviceMethod,
        HttpMethod.GET,
      );
      return response;
    } catch (error) {
      throw new InternalServerErrorException('Failed to fetch routings', error);
    }
  }

  public async findOne(plant: number, id: number): Promise<unknown> {
    const serviceAppId = this.daprConfigService.orderManagementApiAppId;
    const serviceMethod = `routings/${id}?plant=${encodeURIComponent(String(plant))}`;
