  // Materials
  public async listMaterials(
    routingId: number,
    plant: number,
  ): Promise<{ assigned: Array<string>; available: Array<string> }> {
    try {
      // Run both upstream calls in parallel for performance
      const [combinedRespRaw, masterMaterials] = await Promise.all([
        this.fetchroutingMaterials(routingId, plant).catch(() => null),
        this.fetchMasterMaterials(plant),
      ]);
      const extractId = (it: unknown): string | null => {
        if (!it) return null;
        if (typeof it === 'string') return it;
        if (typeof it === 'number') return String(it);
        const rec = it as {
          materialId?: unknown;
          id?: unknown;
          material?: { materialId?: unknown };
        };
        if (typeof rec.materialId === 'string') return rec.materialId;
        if (typeof rec.id === 'string') return rec.id;
        if (rec.material && typeof rec.material.materialId === 'string')
          return rec.material.materialId;
        return null;
      };

      // Normalize combined response
      const combinedResp =
        combinedRespRaw && typeof combinedRespRaw === 'object'
          ? (combinedRespRaw as Record<string, unknown>)
          : null;

      if (
        combinedResp &&
        (Array.isArray(combinedResp.assigned) ||
          Array.isArray(combinedResp.available))
      ) {
        const assignedArray = Array.isArray(combinedResp.assigned)
          ? (combinedResp.assigned as Array<unknown>)
          : [];
        const availableArray = Array.isArray(combinedResp.available)
          ? (combinedResp.available as Array<unknown>)
          : [];

        const assignedIds = assignedArray
          .map((x) => extractId(x))
          .filter((id): id is string => !!id);
        const availableIdsFromResp = availableArray
          .map((x) => extractId(x))
          .filter((id): id is string => !!id);

        const presentIds = new Set<string>([
          ...assignedIds,
          ...availableIdsFromResp,
        ]);

        const additionalFromMaster = (masterMaterials || [])
          .map((m) => m.materialId)
          .filter((id): id is string => !!id && !presentIds.has(id));

        const mergedAvailable = [
          ...availableIdsFromResp,
          ...additionalFromMaster,
        ];

        return { assigned: assignedIds, available: mergedAvailable };
      }

      // Fallback: combinedRespRaw may be an array (assigned list) or a single item
      let assignedArray: Array<MaterialDTL>;
      if (Array.isArray(combinedRespRaw)) {
        assignedArray = combinedRespRaw as Array<MaterialDTL>;
      } else if (combinedRespRaw) {
        assignedArray = [combinedRespRaw as MaterialDTL];
      } else {
        assignedArray = [];
      }

      const assignedIds = assignedArray
        .map((x) => x.materialId)
        .filter((id): id is string => !!id);

      const availableIds: Array<string> = (masterMaterials || [])
        .map((m) => m.materialId)
        .filter((id): id is string => !!id && !assignedIds.includes(id));

      return { assigned: assignedIds, available: availableIds };
    } catch (error) {
      throw new InternalServerErrorException('Failed to list materials', error);
    }
  }

